cat > ~/pyfree/compile_examples.js << 'EOF'
const fs = require('fs');
const path = require('path');
const { PyFreeCompiler } = require('./dist/compiler');

const compiler = new PyFreeCompiler();

const examples = [
  '01_hello_world.pf',
  '02_calculator.pf',
  '03_list_processing.pf'
];

console.log('🚀 PyFree 예제 컴파일 시작\n');
console.log('='.repeat(60));

examples.forEach((example, idx) => {
  const filePath = path.join(__dirname, 'examples', example);
  const code = fs.readFileSync(filePath, 'utf-8');

  console.log(`\n📝 Example ${idx + 1}: ${example}`);
  console.log('-'.repeat(60));

  // 소스 코드 출력
  console.log('📄 Source Code:');
  code.split('\n').slice(0, 10).forEach(line => {
    if (line.trim()) console.log(`   ${line}`);
  });
  if (code.split('\n').length > 10) console.log('   ...');

  try {
    // 컴파일
    console.log('\n⚙️  Compiling...');
    const result = compiler.compile(code);

    if (result.success) {
      console.log('✅ Compilation successful!');
      console.log(`   • IR Instructions: ${result.ir.code.length} commands`);
      console.log(`   • Constants: ${result.ir.constants.length}`);
      console.log(`   • Bytecode size: ${Buffer.byteLength(JSON.stringify(result.ir))} bytes`);

      // IR 코드 일부 출력
      if (result.ir.code.length > 0) {
        console.log('\n   📋 First 3 IR instructions:');
        result.ir.code.slice(0, 3).forEach((instr, i) => {
          console.log(`      [${i}] ${instr.op} ${instr.arg !== undefined ? instr.arg : ''}`);
        });
        if (result.ir.code.length > 3) console.log('      ...');
      }
    } else {
      console.log(`❌ Compilation failed: ${result.error}`);
    }
  } catch (error) {
    console.log(`❌ Error: ${error.message}`);
  }

  console.log('');
});

console.log('='.repeat(60));
console.log('✅ 컴파일 테스트 완료!\n');
EOF
cd ~/pyfree && node compile_examples.js

