cd ~/pyfree && cat > compile_example.js << 'EOF'
const { Lexer, Parser, IRCompiler } = require('./dist');
const fs = require('fs');

const examples = [
  { name: '01_hello_world.pf', path: './examples/01_hello_world.pf' },
  { name: '02_calculator.pf', path: './examples/02_calculator.pf' },
  { name: '03_list_processing.pf', path: './examples/03_list_processing.pf' }
];

console.log('🚀 PyFree 예제 컴파일 시작\n');
console.log('='.repeat(60));

examples.forEach((ex, idx) => {
  console.log(`\n📝 Example ${idx + 1}: ${ex.name}`);
  console.log('-'.repeat(60));

  const code = fs.readFileSync(ex.path, 'utf-8');

  // 소스 코드 출력
  console.log('📄 Source:');
  code.split('\n').slice(0, 8).forEach(line => {
    if (line.trim()) console.log(`   ${line}`);
  });
  if (code.split('\n').length > 8) console.log('   ...');

  try {
    // 렉싱
    console.log('\n⚙️  Lexing...');
    const lexer = new Lexer(code);
    const tokens = lexer.tokenize();
    console.log(`✅ Generated ${tokens.length} tokens`);

    // 파싱
    console.log('\n⚙️  Parsing...');
    const parser = new Parser(tokens);
    const ast = parser.parse();
    console.log(`✅ Generated AST with ${ast.body.length} statements`);

    // 컴파일
    console.log('\n⚙️  Compiling to IR...');
    const compiler = new IRCompiler(ast);
    const ir = compiler.compile();
    console.log(`✅ Generated IR:`);
    console.log(`   • Instructions: ${ir.code.length}`);
    console.log(`   • Constants: ${ir.constants.length}`);
    console.log(`   • Variables: ${ir.variables ? Object.keys(ir.variables).length : 0}`);

    // IR 일부 출력
    if (ir.code.length > 0) {
      console.log('\n   📋 IR Instructions (first 5):');
      ir.code.slice(0, 5).forEach((instr, i) => {
        const arg = instr.arg !== undefined ? ` (${instr.arg})` : '';
        console.log(`      [${i}] ${instr.op}${arg}`);
      });
      if (ir.code.length > 5) console.log(`      ... and ${ir.code.length - 5} more`);
    }

    console.log(`\n✅ SUCCESS: ${ex.name} compiled successfully!`);

  } catch (error) {
    console.log(`\n❌ FAILED: ${error.message}`);
    if (error.stack) {
      console.log(error.stack.split('\n').slice(0, 3).join('\n'));
    }
  }

  console.log('');
});

console.log('='.repeat(60));
console.log('✅ 컴파일 완료!\n');
EOF
