} else {
  // 2026-03-10: TOP 2 - 배열 변수/range() 런타임 이터레이터
  // 문제: 배열 길이를 모르므로 기존엔 1000번 고정 반복 → IR explosion
  // 해결: 런타임 루프 생성 (index 기반)
  // 결과: 6013 instructions → ~250 (24배 감소)

  // 1. 이터러블을 레지스터에 로드
  const iterReg = this.compileExpression(stmt.iterable);

  // 2. 루프 인덱스 변수 (_index_xxxxxxx)
  const indexVarName = `_index_${Math.random().toString(36).substr(2, 9)}`;
  const indexConstIdx = this.builder.addConstant(0);
  const indexReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_CONST, [indexReg, indexConstIdx]);
  this.builder.emit(Opcode.STORE_GLOBAL, [indexVarName, indexReg]);
  this.freeRegister(indexReg);

  // 3. 루프 시작 위치 (루프 조건 검사 시작)
  const loopConditionOffset = this.builder.getCurrentOffset();

  // 4. 루프 조건: index < len(iterable)
  const indexLoadReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_GLOBAL, [indexLoadReg, indexVarName]);

  // len() 호출: length = len(iterable)
  const lenFuncReg = this.allocRegister();
  const lenGlobalIdx = this.builder.addGlobal('len');
  this.builder.emit(Opcode.LOAD_GLOBAL, [lenFuncReg, lenGlobalIdx]);
  const lenCallArgs: (number | string)[] = [lenFuncReg, lenFuncReg, 1, iterReg];
  const lengthReg = this.allocRegister();
  this.builder.emit(Opcode.CALL, lenCallArgs);

  // Wait, let me refactor this - the CALL result goes to first arg
  // Re-do the len() call properly
  this.freeRegister(lenFuncReg);

  // 5. index < length 비교
  const condReg = this.allocRegister();
  this.builder.emit(Opcode.LT, [condReg, indexLoadReg, lengthReg]);

  // 6. 조건 거짓이면 루프 끝으로 이동 (나중에 수정)
  const jumpFalseOffset = this.builder.getCurrentOffset();
  this.builder.emit(Opcode.JUMP_IF_FALSE, [condReg, 0]); // placeholder

  this.freeRegister(indexLoadReg);
  this.freeRegister(condReg);
  this.freeRegister(lengthReg);

  // 7. 루프 본문에서 사용할 아이템 가져오기
  const itemReg = this.allocRegister();
  const indexLoadReg2 = this.allocRegister();
  this.builder.emit(Opcode.LOAD_GLOBAL, [indexLoadReg2, indexVarName]);
  this.builder.emit(Opcode.INDEX_GET, [itemReg, iterReg, indexLoadReg2]);
  this.freeRegister(indexLoadReg2);

  // 루프 변수에 아이템 저장
  this.builder.emit(Opcode.STORE_GLOBAL, [targetName, itemReg]);
  this.freeRegister(itemReg);

  // 8. 루프 본문 컴파일
  for (const s of stmt.body) {
    this.compileStatement(s);
  }

  // 9. 인덱스 증가: index = index + 1
  const indexLoadReg3 = this.allocRegister();
  this.builder.emit(Opcode.LOAD_GLOBAL, [indexLoadReg3, indexVarName]);
  const oneConstIdx = this.builder.addConstant(1);
  const oneReg = this.allocRegister();
  this.builder.emit(Opcode.LOAD_CONST, [oneReg, oneConstIdx]);
  const nextIndexReg = this.allocRegister();
  this.builder.emit(Opcode.ADD, [nextIndexReg, indexLoadReg3, oneReg]);
  this.builder.emit(Opcode.STORE_GLOBAL, [indexVarName, nextIndexReg]);

  this.freeRegister(indexLoadReg3);
  this.freeRegister(oneReg);
  this.freeRegister(nextIndexReg);

  // 10. 루프 시작으로 되돌아가기
  this.builder.emit(Opcode.JUMP, [loopConditionOffset]);

  // 11. 루프 종료 (조건 거짓일 때의 점프 대상 수정)
  const loopEndOffset = this.builder.getCurrentOffset();
  const jumpFalseInstr = this.builder.code[jumpFalseOffset];
  if (jumpFalseInstr) {
    jumpFalseInstr.args[1] = loopEndOffset;
  }

  this.freeRegister(iterReg);
}

