  const jumpFalseOffset = this.builder.getCurrentOffset();
  this.builder.emit(Opcode.JUMP_IF_FALSE, [condReg, 0]); // placeholder

  this.freeRegister(indexLoadReg);
  this.freeRegister(condReg);
  this.freeRegister(lengthReg);

  // 7. 루프 본문에서 사용할 아이템 가져오기
  const itemReg = this.allocRegister();
  const indexLoadReg2 = this.allocRegister();
  this.builder.emit(Opcode.LOAD_GLOBAL, [indexLoadReg2, indexVarName]);
  this.builder.emit(Opcode.INDEX_GET, [itemReg, iterReg, indexLoadReg2]);
