const { tokenize } = require('./dist/lexer/lexer');
const { parse } = require('./dist/parser/parser');
const { IRCompiler } = require('./dist/runtime/ir');

const code = \`def add(a, b):
    return a + b

result = add(10, 5)
print(result)\`;

try {
  const tokens = tokenize(code);
  const ast = parse(tokens);
  const ir = new IRCompiler().compile(ast);

  console.log('Main IR Instructions:', ir.code.length);
  console.log('Functions:', ir.functions.size);
  ir.functions.forEach((func, name) => {
    console.log(\`  \${name}: \${func.code.length} instructions, \${func.paramCount} params\`);
  });

  console.log('\\nMain Instructions:');
  ir.code.forEach((instr, i) => {
    console.log(\`  \${i}: \${instr.op.padEnd(15)} \${JSON.stringify(instr.args).slice(0, 60)}\`);
  });
} catch (e) {
  console.log('Error:', e.message);
  console.log(e.stack);
}
"

