 * AST 컴파일
 */
compile(ast: any): IRProgram {
  if (!ast || ast.type !== 'Program') {
    return this.builder.build();
  }

  const program = ast as any;

  // 2026-03-10: TOP 3 - 함수 정의 직접 컴파일
  // 모든 statement를 순서대로 컴파일하되,
  // FunctionDef는 메인 코드에 포함하되 JUMP로 건너뜀
  const functionOffsets: Map<string, number> = new Map();

  // 1단계: 함수 정의 위치 기록 (추후 JUMP 수정용)
  let mainCodeStartOffset = 0;
  for (const stmt of program.body) {
    if (stmt.type === 'FunctionDef' || stmt.type === 'FreeLangFunction') {
      functionOffsets.set(stmt.name, -1); // 나중에 업데이트
    }
  }

  // 2단계: 모든 코드 컴파일
  const skipJumps: { offset: number; targetName?: string }[] = [];
  for (const stmt of program.body) {
    if (stmt.type === 'FunctionDef' || stmt.type === 'FreeLangFunction') {
      // 함수 정의는 SKIP (JUMP로 건너뜀)
      this.compileFunctionDef(stmt);
    } else {
      // 나머지 코드는 정상 컴파일
      this.compileStatement(stmt);
    }
  }

  return this.builder.build();
}

