/**
 * AST 컴파일
 */
compile(ast: any): IRProgram {
  if (!ast || ast.type !== 'Program') {
    return this.builder.build();
  }

  const program = ast as any;

  // 2026-03-10: TOP 3 - 함수 정의를 먼저 수집
  // 1단계: 함수 정의만 처리 (메인 코드에서 제외)
  const functionJumps: { offset: number; targetOffset: number }[] = [];
  for (const stmt of program.body) {
    if (stmt.type === 'FunctionDef' || stmt.type === 'FreeLangFunction') {
      this.compileFunctionDef(stmt);
    }
  }

  // 2단계: 메인 코드의 함수 정의를 제거하고 JUMP 추가
  // (함수 정의 코드를 메인 코드에서 제거)
  let functionsCodeStart = -1;
  let functionsCodeEnd = -1;

  // 함수 정의 코드 범위 찾기
  for (let i = 0; i < this.builder.code.length; i++) {
    const instr = this.builder.code[i];
    // 함수 정의는 LOAD_FAST로 시작 (파라미터 로드)
    if (instr.op === 'LOAD_FAST' && i < 10) {
      // 이것이 함수 정의의 시작일 수 있음
      if (functionsCodeStart === -1 && this.builder.code[i + 3]?.op === 'RETURN') {
        functionsCodeStart = i;
      }
    }
  }

  // 실제로 함수 정의 코드를 찾는 더 정확한 방법:
  // 모든 statement를 다시 처리하되, 함수 정의는 건너뛰기
  this.builder.code = []; // 코드 초기화

  // 2-1단계: 함수들을 이미 수집했으므로, 메인 코드만 컴파일
  for (const stmt of program.body) {
    if (stmt.type !== 'FunctionDef' && stmt.type !== 'FreeLangFunction') {
      this.compileStatement(stmt);
    }
  }

  return this.builder.build();
}

