private parsePrimary(): AST.Expression {
  const token = this.peek();

  // 리터럴
  if (this.check(TokenType.NUMBER)) {
    const value = this.advance();
    // 숫자 문자열을 숫자로 변환
    let numValue: number;
    if (typeof value.value === 'string') {
      if (value.value.startsWith('0x')) {
        numValue = parseInt(value.value, 16);
      } else if (value.value.startsWith('0b')) {
        numValue = parseInt(value.value.slice(2), 2);
      } else {
        numValue = parseFloat(value.value);
      }
    } else {
      numValue = value.value;
    }
    return {
      type: 'Literal',
      valueType: 'number',
      value: numValue,
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  if (this.check(TokenType.STRING)) {
    const value = this.advance();
    return {
      type: 'Literal',
      valueType: 'string',
      value: value.value,
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  if (this.check(TokenType.F_STRING)) {
    return this.parseFormattedString();
  }

  if (this.check(TokenType.TRUE)) {
    const value = this.advance();
    return {
      type: 'Literal',
      valueType: 'boolean',
      value: true,
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  if (this.check(TokenType.FALSE)) {
    const value = this.advance();
    return {
      type: 'Literal',
      valueType: 'boolean',
      value: false,
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  if (this.check(TokenType.NONE)) {
    const value = this.advance();
    return {
      type: 'Literal',
      valueType: 'none',
      value: null,
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  if (this.check(TokenType.ELLIPSIS)) {
    const value = this.advance();
    return {
      type: 'Literal',
      valueType: 'ellipsis',
      value: '...',
      line: value.line,
      column: value.column,
    } as AST.Literal;
  }

  // 식별자
  if (this.check(TokenType.IDENTIFIER)) {
    const value = this.advance();
    return {
      type: 'Identifier',
      name: value.value,
      line: value.line,
      column: value.column,
    } as AST.Identifier;
  }

