     1→/**
     2→ * PyFree VM (Virtual Machine)
     3→ * IR을 실행하는 가상 머신
     4→ *
     5→ * 구조:
     6→ * - 레지스터: 256개
     7→ * - 콜 스택: 함수 호출
     8→ * - 루프 스택: break/continue
     9→ * - 예외 처리
    10→ */
    11→
    12→import { IRProgram, Instruction, Opcode, IRFunction } from './ir';
    13→
    14→/**
    15→ * 런타임 값
    16→ */
    17→export type PyFreeValue = any;
    18→
    19→/**
    20→ * 호출 프레임
    21→ */
    22→interface Frame {
    23→  function?: IRFunction;
    24→  code: Instruction[];
    25→  pc: number;  // Program Counter
    26→  registers: PyFreeValue[];
    27→  locals: Map<string, PyFreeValue>;
    28→  returnValue?: PyFreeValue;
    29→  callDstReg?: number; // 2026-03-10: 함수 반환값을 저장할 호출자 레지스터
    30→}
    31→
    32→/**
    33→ * 루프 컨텍스트
    34→ */
    35→interface LoopContext {
    36→  startOffset: number;
    37→  endOffset: number;
    38→}
    39→
    40→/**
    41→ * 예외 핸들러
    42→ */
    43→interface ExceptionHandler {
    44→  offset: number;
    45→  endOffset?: number;
    46→}
    47→
    48→/**
    49→ * PyFree VM
    50→ */
    51→export class VM {
    52→  private program: IRProgram;
    53→  private registers: PyFreeValue[] = new Array(256);
    54→  private frameStack: Frame[] = [];
    55→  private loopStack: LoopContext[] = [];
    56→  private handlerStack: ExceptionHandler[] = [];
