#!/usr/bin/env node

/**
 * FOR 루프 디버깅 테스트
 * 상세한 VM 실행 로그를 통해 무한반복 원인 파악
 */

const fs = require('fs');
const path = require('path');

// 프로젝트 루트
const ROOT = path.join(__dirname, '.');

// 빌드된 모듈 로드
const { Lexer } = require(path.join(ROOT, 'dist/lexer.js'));
const { Parser } = require(path.join(ROOT, 'dist/parser.js'));
const { IRCompiler } = require(path.join(ROOT, 'dist/runtime/ir.js'));
const { VM, NativeLibrary } = require(path.join(ROOT, 'dist/runtime/vm.js'));

// 테스트 코드
const testCode = `
for i in range(3):
    print(i)
`;

console.log('=== FOR 루프 디버깅 테스트 ===\n');
console.log('테스트 코드:');
console.log(testCode);
console.log('\n' + '='.repeat(50) + '\n');

// 1. 렉싱
console.log('[1] 렉싱...');
const lexer = new Lexer(testCode);
const tokens = lexer.tokenize();
console.log(`✓ ${tokens.length}개 토큰 생성\n`);

// 2. 파싱
console.log('[2] 파싱...');
const parser = new Parser(tokens);
const ast = parser.parse();
console.log(`✓ AST 생성\n`);

// 3. IR 컴파일
console.log('[3] IR 컴파일...');
const compiler = new IRCompiler();
const program = compiler.compile(ast);

console.log(`✓ IR 생성`);
console.log(`  - 명령어: ${program.code.length}개`);
console.log(`  - 상수풀: ${program.constants.length}개`);
console.log(`  - 전역변수: ${program.globals.size}개\n`);

// 4. 상수풀 출력
console.log('[4] 상수풀:');
program.constants.forEach((val, idx) => {
  console.log(`  [${idx}] = ${JSON.stringify(val)}`);
});
console.log();

// 5. IR 디스어셈블리
console.log('[5] IR 명령어:');
const opcodeNames = {
  0: 'LOAD_CONST',
  1: 'LOAD_GLOBAL',
  2: 'LOAD_FAST',
  3: 'LOAD_NONE',
  4: 'LOAD_TRUE',
  5: 'LOAD_FALSE',
  10: 'STORE_GLOBAL',
  11: 'STORE_FAST',
  20: 'ADD',
  21: 'SUB',
  22: 'MUL',
  23: 'DIV',
  24: 'MOD',
  30: 'LT',
  31: 'LE',
  32: 'GT',
  33: 'GE',
  34: 'EQ',
  35: 'NE',
  40: 'AND',
  41: 'OR',
  42: 'IN',
  50: 'JUMP',
  51: 'JUMP_IF_FALSE',
  52: 'JUMP_IF_TRUE',
  60: 'CALL',
  61: 'RETURN',
  70: 'BUILD_LIST',
  71: 'BUILD_DICT',
  72: 'INDEX_GET',
  73: 'INDEX_SET',
  74: 'ATTR_GET',
  75: 'ATTR_SET',
  80: 'SETUP_LOOP',
  81: 'POP_LOOP',
  82: 'BREAK',
  83: 'CONTINUE',
  90: 'NOP',
  91: 'PRINT',
  92: 'POP_TOP',
};

program.code.forEach((instr, idx) => {
  const opName = opcodeNames[instr.op] || `OP_${instr.op}`;
  const args = instr.args
    .map(a => {
      if (typeof a === 'string') return `"${a}"`;
      return a;
    })
    .join(', ');
  console.log(`  ${idx.toString().padStart(2, '0')}: ${opName.padEnd(18)} [${args}]`);
});
console.log();

// 6. 수정된 VM 클래스 (디버그 로깅 추가)
class DebugVM extends VM {
  constructor(program) {
    super(program);
    this.executionLog = [];
    this.stepCount = 0;
    this.maxSteps = 200; // 무한루프 방지
  }

  executeInstruction(instr, frame) {
    this.stepCount++;

    if (this.stepCount > this.maxSteps) {
      console.log(`\n❌ 실행 단계 초과 (${this.maxSteps}회). 무한루프 감지!`);
      this.halted = true;
      return;
    }

    const [a, b, c] = instr.args;
    const aNum = typeof a === 'number' ? a : 0;
    const bNum = typeof b === 'number' ? b : 0;
    const cNum = typeof c === 'number' ? c : 0;

    const opName = opcodeNames[instr.op] || `OP_${instr.op}`;

    // 특정 명령어만 로깅
    const interestingOps = [1, 10, 30, 50, 51, 60, 91]; // LOAD_GLOBAL, STORE_GLOBAL, LT, JUMP, JUMP_IF_FALSE, CALL, PRINT

    if (interestingOps.includes(instr.op)) {
      const logEntry = {
        step: this.stepCount,
        pc: frame.pc - 1,
        op: opName,
        args: instr.args,
      };

      // 각 명령어 타입별 상세 로깅
      if (instr.op === 1) {
        // LOAD_GLOBAL
        const value = this.globals.get(String(b));
        logEntry.detail = `reg[${aNum}] = globals["${b}"] = ${JSON.stringify(value)}`;
      } else if (instr.op === 10) {
        // STORE_GLOBAL
        const value = frame.registers[bNum];
        logEntry.detail = `globals["${a}"] = reg[${bNum}] = ${JSON.stringify(value)}`;
      } else if (instr.op === 30) {
        // LT
        const left = frame.registers[bNum];
        const right = frame.registers[cNum];
        logEntry.detail = `reg[${aNum}] = (reg[${bNum}] < reg[${cNum}]) = (${left} < ${right}) = ${left < right}`;
      } else if (instr.op === 50) {
        // JUMP
        logEntry.detail = `pc = ${bNum}`;
      } else if (instr.op === 51) {
        // JUMP_IF_FALSE
        const condition = frame.registers[aNum];
        logEntry.detail = `if (!reg[${aNum}]) pc = ${bNum};  (condition=${condition})`;
      } else if (instr.op === 60) {
        // CALL
        const func = frame.registers[bNum];
        logEntry.detail = `Call function in reg[${bNum}] → dst reg[${aNum}]`;
      } else if (instr.op === 91) {
        // PRINT
        const value = frame.registers[aNum];
        logEntry.detail = `print(reg[${aNum}]) = ${JSON.stringify(value)}`;
      }

      this.executionLog.push(logEntry);
      console.log(
        `[${this.stepCount.toString().padStart(3)}] PC=${(frame.pc - 1).toString().padStart(2)} ${opName.padEnd(18)} ${logEntry.detail || ''}`
      );
    }

    // 실제 실행
    super.executeInstruction(instr, frame);
  }
}

// 7. VM 실행
console.log('[6] VM 실행 (상세 로그):\n');

const vmWithNatives = new DebugVM(program);

// 전역 함수 등록
Object.entries(NativeLibrary).forEach(([name, func]) => {
  vmWithNatives.setGlobal(name, func);
});

vmWithNatives.execute();

// 8. 결과 출력
console.log('\n' + '='.repeat(50));
console.log(`\n✓ 실행 완료 (${vmWithNatives.stepCount}회 단계)`);

const output = vmWithNatives.getOutput();
console.log('\n출력 결과:');
if (output.length === 0) {
  console.log('  (없음)');
} else {
  output.forEach(line => console.log(`  ${line}`));
}

console.log('\n실행 로그:');
vmWithNatives.executionLog.forEach(log => {
  console.log(
    `  [${log.step.toString().padStart(3)}] PC=${log.pc
      .toString()
      .padStart(2)} ${log.op.padEnd(18)} ${log.detail}`
  );
});

// 9. 분석
console.log('\n' + '='.repeat(50));
console.log('\n📊 분석:');

// 루프 점프 패턴 분석
const jumps = vmWithNatives.executionLog.filter(l => ['JUMP', 'JUMP_IF_FALSE'].includes(l.op));
console.log(`\n  점프 명령어: ${jumps.length}회`);
jumps.forEach((j, i) => {
  const detail = j.detail.match(/pc = (\d+)/);
  console.log(
    `    ${i + 1}. ${j.op} at PC=${j.pc} → target PC=${detail ? detail[1] : '?'}`
  );
});

// PRINT 횟수
const prints = vmWithNatives.executionLog.filter(l => l.op === 'PRINT');
console.log(`\n  PRINT 호출: ${prints.length}회`);
prints.forEach((p, i) => {
  console.log(`    ${i + 1}. ${p.detail}`);
});

console.log('\n');

