const opcodeNames = {
  0: 'LOAD_CONST',
  1: 'LOAD_GLOBAL',
  2: 'LOAD_FAST',
  3: 'LOAD_NONE',
  4: 'LOAD_TRUE',
  5: 'LOAD_FALSE',
  10: 'STORE_GLOBAL',
  11: 'STORE_FAST',
  20: 'ADD',
  21: 'SUB',
  22: 'MUL',
  23: 'DIV',
  24: 'MOD',
  30: 'LT',
  31: 'LE',
  32: 'GT',
  33: 'GE',
  34: 'EQ',
  35: 'NE',
  40: 'AND',
