def tokenize(source):
    # 키워드 목록
    keywords = ["def", "if", "return", "else", "for", "while", "break", "continue", "class", "import", "from", "as", "pass", "True", "False", "None", "and", "or", "not", "in", "is", "lambda", "print"]

    tokens = []
    words = source.split(" ")

    i = 0
    while i < len(words):
        word = words[i]

        # 빈 문자열 건너뛰기
        if word == "":
            i = i + 1
            continue

        # 키워드 판정 - 간단한 문자열 비교
        is_keyword = False

        if word == "def":
            is_keyword = True
        elif word == "if":
            is_keyword = True
        elif word == "return":
            is_keyword = True
        elif word == "else":
            is_keyword = True
        elif word == "for":
            is_keyword = True
        elif word == "while":
            is_keyword = True
        elif word == "class":
            is_keyword = True
        elif word == "import":
            is_keyword = True
        elif word == "print":
            is_keyword = True

        # 토큰 생성
        if is_keyword:
            token = {"type": "KEYWORD", "value": word}
        else:
            token = {"type": "IDENT", "value": word}

        tokens.append(token)
        i = i + 1

    return tokens

