   599→  print: (...args: PyFreeValue[]): null => {
   600→    console.log(args.map((a) => String(a)).join(' '));
   601→    return null;
   602→  },
   603→
   604→  // 길이
   605→  len: (obj: PyFreeValue): number => {
   606→    if (Array.isArray(obj)) return obj.length;
   607→    if (typeof obj === 'string') return obj.length;
   608→    if (typeof obj === 'object') return Object.keys(obj).length;
   609→    return 0;
   610→  },
   611→
   612→  // 범위
   613→  range: (start: number, end?: number, step?: number): number[] => {
