def is_whitespace(c):
    if c == " ":
        return True
    if c == "\t":
        return True
    if c == "\n":
        return True
    return False

def is_alpha(c):
    code = ord(c)
    if code >= 97 and code <= 122:
        return True
    if code >= 65 and code <= 90:
        return True
    return False

def is_digit(c):
    code = ord(c)
    if code >= 48 and code <= 57:
        return True
    return False

def is_alnum(c):
    if is_alpha(c):
        return True
    if is_digit(c):
        return True
    if c == "_":
        return True
    return False

def is_keyword_word(word):
    if word == "def":
